			/*
			 * "저장" 버튼(btn3)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtn3Click(e) {
			    var btn3 = e.control;
			    var dsWorkDiary = app.lookup("dsWorkDiary").getRow(0);
			    var dsWorkCnList = app.lookup("dsWorkCnList");
			    var dsYngbgsObservRcordList = app.lookup("dsYngbgsObservRcordList");
			    
			    if (!util.validate(app, "grpSearch")) return false;
			    
			    for (var i = 0; i < dsWorkCnList.getRowCount(); i++) {
			        if (!dsWorkCnList.getValue(i, "BGNG_HR")) {
			            util.Msg.alert(app, "WRN-M001", "근무내용 추가/수정시 시작시간");
			            app.lookup("grd1").focusCell(i, "BGNG_HR");
			            return false;
			        }
			        if (!dsWorkCnList.getValue(i, "END_HR")) {
			            util.Msg.alert(app, "WRN-M001", "근무내용 추가/수정시 종료시간");
			            app.lookup("grd1").focusCell(i, "END_HR");
			            return false;
			        }
			        if (!dsWorkCnList.getValue(i, "WORK_CN")) {
			            util.Msg.alert(app, "WRN-M001", "근무내용 추가/수정시 근무내용");
			            app.lookup("grd1").focusCell(i, "WORK_CN");
			            return false;
			        }
			    }
			    
			    var alert = '';
			    for (var idx = 0; idx < dsYngbgsObservRcordList.getRowCount(); idx++) {
			        if (dsYngbgsObservRcordList.getValue(idx, "PERIOD_MEDCIN_TAKNG_SE_CD") == "" || dsYngbgsObservRcordList.getValue(idx, "PERIOD_MEDCIN_TAKNG_SE_CD") == null) {
			            alert = "모든 대상자에 대한 정기적인 약 복용 여부를 체크해주셔야 합니다.";
			            break;
			        } else if (dsYngbgsObservRcordList.getValue(idx, "PERIOD_MEDCIN_TAKNG_SE_CD") != 1) {
			            if (dsYngbgsObservRcordList.getValue(idx, "PERIOD_MEDCIN_TAKNG") == "" || dsYngbgsObservRcordList.getValue(idx, "PERIOD_MEDCIN_TAKNG") == null) {
			                alert = "정기적인 약 복용을 하는 대상자는 복용시기를 선택해주셔야합니다.";
			            }
			        }
			    }
			    if (alert) {
			        util.Msg.alert(app, alert);
			        return false;
			    }
			    
			    util.Msg.confirm(app, "CRM-M001", null, function() {
			        
			        dsWorkCnList.getRowStatedIndices(cpr.data.tabledata.RowState.MODIFIED).forEach(function(idx) {
			            
			            dsWorkCnList.setValue(idx, "SRVC_EXCN_BIZ_NO", dsWorkDiary.getValue("SRVC_EXCN_BIZ_NO"));
			            dsWorkCnList.setValue(idx, "ALTMNT_GROUP_SCLAS_SE_CD", dsWorkDiary.getValue("ALTMNT_GROUP_SCLAS_SE_CD"));
			            dsWorkCnList.setValue(idx, "WRT_YMD", dsWorkDiary.getValue("WRT_YMD"));
			        });
			        
			        dsYngbgsObservRcordList.getRowStatedIndices(cpr.data.tabledata.RowState.MODIFIED).forEach(function(idx) {
			            
			            dsYngbgsObservRcordList.setValue(idx, "WRT_YMD", dsWorkDiary.getValue("WRT_YMD"));
			        });
			        
			        doSave("save");
			    });
			}

